head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
 ASIS에서 문법에 어긋난 문장이 발견되었습니다. 이는 WCRAFT에서 X 로 변환합니다.  
 X 로 변환된 곳을 찾아 ASIS소스를 참고하여 문법에 맞도록 변환해주세요. 

----------------------------------------------------
[0] 기존 문법 오류
----------------------------------------------------
	> X 오류 확인 - 기존 소스 확인 필요

*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
// showObj(ObjID, flag) SetWindowPos(ObjID, nTop, nLeft, nWidth, nHeight)
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/json2.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/report.js");
scwin.vScrenID = "ULDSTF05411.xml";
scwin.vScrenTpCD = "";
scwin.vCurDate = $c.ut.cGetToday("yyyymmdd");
scwin.Tpcd = "4";
//var vSecugrpID = SECUGRP_ID_ST; //(주권)메뉴단에서 파라미터로 받자..
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID());
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
}; // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조. 

scwin.fn_GetParStdInd = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = $c.stf.getObjectValue(txb_IsurCd); // 코드값을 포함할 컨트롤
    arrPar[1] = $c.stf.getObjectValue(txb_IsurNm); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤
    //arrPar[2] = vSecugrpID;	  						     // 명칭값을 포함할 컨트롤
    return
    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************
    arrPar, length;
};
scwin.fn_SetParStdInd = function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    scwin.fn_init();
};
scwin.fn_Search_list = function() {
    //dts_IndustryChange.NameValue(1,"BZ_PROCS_NO")= fr_bz_procs_no;
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchlist&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT" + "&ISUR_CD=" + txb_IsurCd.getValue();
    dts_list.DataID = encodeURI(url);
    dts_list.Reset();
};
scwin.fn_Search_Detaillist = function(isur_cd) {
    //dts_IndustryChange.NameValue(1,"BZ_PROCS_NO")= fr_bz_procs_no;
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchdetaillist&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT" + "&ISUR_CD=" + isur_cd;
    dts_detaillist.DataID = encodeURI(url);
    dts_detaillist.Reset();
};
scwin.fn_Search_delistMaster = function(bzprocscd) {
    var BZ_PROCS_NO = bzprocscd;
    var url = "/Delisting.do";
    url += "?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=incoSearchMaster&inputMessageId=DELISTING_INOUT&outputMessageId=DELISTING_INOUT&ISUR_CD=" + txb_IsurCd.getValue() + "&BZ_PROCS_NO=" + BZ_PROCS_NO;
    dts_delistMaster.DataID = encodeURI(url);
    dts_delistMaster.Reset();
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_IsurCd) == "") {
        $c.win.alert("[위탁회사]를 선택하세요.");
        txb_IsurNm.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_title) == "") {
        $c.win.alert("[제목]를 입력하세요.");
        txb_title.focus();
        return false;
    } else {
        if (!$c.stf.checkMaxLength(txb_title, 500, "제목")) return false;
    }
    if (txb_ISU_KOR_NM.getValue() == "") {
        $c.win.alert("[종목명]을 입력하세요.");
        txb_ISU_KOR_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_ISU_CD) == "") {
        // 추가
        $c.win.alert("[종목]을 선택하세요.");
        return false;
    }
    if (txa_DELIST_ADVNOTI_RSN.Text == "") {
        $c.win.alert("[상장폐지 예고사유]를 입력하세요.");
        txa_DELIST_ADVNOTI_RSN.focus();
        return false;
    }
    if (edt_TRST_END_DD.getValue() == "") {
        $c.win.alert("[신탁기간 만료일]을 입력하세요.");
        edt_TRST_END_DD.focus();
        return false;
    }
    return true;
};
scwin.fn_save = function() {
    TR_JOB = 'I';
    if (scwin.fn_CheckForm()) {
        if (!$c.lc.fn_isProcess(TR_JOB)) return;
        vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        //alert("[저장 vBzProcsNo]"+vBzProcsNo);
        if (vBzProcsNo.length != 14) {
            $c.win.alert("업무처리번호생성실패");
        } else {

            // ********************************************************************
            // [WebSquare 전환 추가] 원본 소스와 비교 필요
            // 
            // ********************************************************************

            /*ORG SRC: dts_delistMaster.UserStatus(1) = TB_JOB_INSERT;*/
            X = TB_JOB_INSERT;
            dts_delistMaster.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
            dts_delistMaster.setCellData(1, "INFO_CONTN_TP_CD", scwin.Tpcd);
            scwin.fn_trs(vBzProcsNo);
        }
    }
};
scwin.fn_update = function() {
    TR_JOB = 'U';
    var code = "";
    if (scwin.fn_CheckForm()) {

        // ********************************************************************
        // [WebSquare 전환 추가] 원본 소스와 비교 필요
        // 
        // ********************************************************************

        if (!$c.lc.fn_isProcess(TR_JOB)) return; /*ORG SRC: dts_delistMaster.UserStatus(1) = TB_JOB_UPDATE;;*/ X = TB_JOB_UPDATE;
        var ProcsNo = dts_delistMaster.getCellData(1, "BZ_PROCS_NO");
        scwin.fn_trs(ProcsNo);
    }
};
scwin.fn_trs = function(pProcsNo) {
    if (TR_JOB == 'I') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
    } else if (TR_JOB == 'U') {
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_03;
    }
    dts_delistinsert.removeAll();
    dts_delistinsert.removeAll();
    dts_delistinsert.insertRow();
    dts_delistinsert.setCellData(1, "BZ_PROCS_NO", pProcsNo);
    dts_delistinsert.setCellData(1, "ISU_CD", txb_ISU_CD.getValue());
    trs_update.Action = $c.lc.fn_encodeNSession("/Delisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=delistsave");
    trs_update.KeyName = "toinb_dataid4";
    trs_update.KeyValue = "JSP(I:pInput=dts_delistMaster,I:pGrid=dts_delistinsert)";
    trs_update.Post();
};
scwin.fn_delete = function() {

    // ********************************************************************
    // [WebSquare 전환 추가] 원본 소스와 비교 필요
    // 
    // ********************************************************************

    TR_JOB = 'D';
    scwin.vScrenTpCD = SCREN_PROCS_TP_CD_04;
    if (!$c.lc.fn_isProcess(TR_JOB)) return; /*ORG SRC: dts_delistMaster.UserStatus(1) = TB_JOB_DELETE;*/ X = TB_JOB_DELETE;
    var vBzProcsNo = dts_delistMaster.getCellData(1, "BZ_PROCS_NO");
    dts_delistMaster.setCellData(1, "BZ_PROCS_NO", vBzProcsNo);
    scwin.fn_delete_trs();
};
scwin.fn_delete_trs = function() {
    trs_delete.Action = $c.lc.fn_encodeNSession("/Delisting.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=delistsave");
    trs_delete.KeyName = "toinb_dataid4";
    trs_delete.KeyValue = "JSP(I:pInput=dts_delistMaster,I:pGrid=dts_delistinsert)";
    trs_delete.Post();
};
scwin.fn_init = function() {
    txb_title.setValue("");
    txb_ISU_KOR_NM.setValue("");
    txa_DELIST_ADVNOTI_RSN.Text = "";
    edt_TRST_END_DD.setValue("");
    txa_GRND_REGUL_CONTN.Text = "";
    txa_REMK.Text = "";
    txb_ISU_CD.setValue("");
};
scwin.fn_dscl = async function() {
    if (!scwin.fn_CheckForm()) return;
    /*
    	if(  dts_Mst.IsUpdated || dts_Isu.IsUpdated || dts_Rsn.IsUpdated ) {
    		alert(getMessageParam("MSG-0022", ""));
    		return ;
    	}
    */
    var OldGet = fn_GetPar;
    var OldSet = fn_SetPar;
    scwin.fn_dscl_dataformat();
    fn_GetPar = function(arr, param_dts_isu, param_dts_mst, param_dts2, param_dts3) {
        arr[0] = "68909A"; //수익증권 상장폐지예고
        arr[1] = dts_delistMaster.getCellData(1, "BZ_PROCS_NO");
        arr[2] = $c.stf.getObjectValue(txb_IsurCd);
        arr[3] = '1';
        //arr[4] = txbcontent.text;
        arr[5] = $c.stf.getObjectValue(txb_title);
        $c.stf.CopyDataSet(dts_detaillist, param_dts_isu, "rowFrom=" + dts_detaillist.getRowPosition() + ",rowCnt=1");
        $c.stf.CopyDataSet(dts_delistMaster, param_dts_mst);
        return arr.length;
    };
    fn_SetPar = function(arr) {

    };
    var wth = 730 + 5;
    var hgt = 785 + 30;
    var pt = $c.stf.fn_getModalCenterPos(frame, wth, hgt);
    await $c.frame.CreateDialogFrame("ULDSTF92024", "/listingcommon/ULDSTF92024.gfm", "공시안내문작성", pt.x, pt.y, wth, hgt, "window");
    fn_GetPar = OldGet;
    fn_SetPar = OldSet;
};
scwin.fn_dscl_dataformat = function() {
    dts_delistMaster.setCellData(1, "TRST_YY", $c.stf.getObjectValue(edt_TRST_END_DD).substring(0, 4));
    dts_delistMaster.setCellData(1, "TRST_MM", $c.stf.getObjectValue(edt_TRST_END_DD).substring(4, 6));
    dts_delistMaster.setCellData(1, "TRST_DD", $c.stf.getObjectValue(edt_TRST_END_DD).substring(6, 8));
};



/********************************************** 
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print = function() {
    var sDepNm_1 = "";
    var sDepNm_2 = "";

    //PDF 리포트 파일명 
    var pdf_rptname = "RLDSTF00004";
    var contents = "1.상장폐지 예고대상 수익증권:" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "ISU_KOR_NM") + "수익증권 상장폐지 예고\n";
    contents += "2.상장폐지 예고사유 : 신탁기간만료(" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "DELIST_ADVNOTI_RSN") + "\n";
    contents += "3.신탁기간 만료일:" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(0, 4) + "." + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(4, 6) + "." + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "TRST_END_DD").substring(6, 8) + "\n";
    contents += "4.근거규정 :" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "GRND_REGUL_CONTN") + "\n";
    contents += "5.기타 투자판단에 참고할 사항 :" + dts_delistMaster.getCellData(dts_delistMaster.getRowPosition(), "REMK") + "\n\n";
    contents = $c.ut.replaceAll(contents, '\n', '<br>');
    contents = $c.ut.replaceAll(contents, ' ', '&nbsp;');
    var userParam = [{
        uid: "DEP_NM_1",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_1)
    }, {
        uid: "DEP_NM_2",
        unm: $c.ut.defaultStrHtmlSpace(sDepNm_2)
    }, {
        uid: "ISUR_CD",
        unm: $c.ut.defaultStrHtmlSpace($c.stf.getObjectValue(txb_IsurCd))
    }, {
        uid: "COM_NM",
        unm: $c.ut.defaultStrHtmlSpace($c.stf.getObjectValue(txb_IsurNm))
    }, {
        uid: "TITLE",
        unm: $c.ut.defaultStrHtmlSpace($c.stf.getObjectValue(txb_title))
    }, {
        uid: "BODY",
        unm: contents
    }];
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);

    //PDF Convert
    $c.rpt.fn_open_report_pdf(pdf_rptname, userParam);
};



/********************************************** 
 * ASIS rexpert-bak 2018-04-03
 * 함수명   : Print()
 * 설명       : 화면을 인쇄한다. 
 ***********************************************/
scwin.fn_print_old = function() {

    //dts_Print.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    //껍데기만 만들고 사용자필드를 사용함
    dts_Print.insertRow();

    //데이타셋 
    var testDateSet = rex_gfGetGauceCsvStr(dts_Print);

    //Rexpert리포트 파일명 
    var rex_rptname = "RLDSTF00004";
    var contents = "1.상장폐지 예고대상 수익증권:" + dts_delistMaster.getCellData(1, "ISU_KOR_NM") + "수익증권 상장폐지 예고\n";
    contents += "2.상장폐지 예고사유 : 신탁기간만료(" + dts_delistMaster.getCellData(1, "DELIST_ADVNOTI_RSN") + "\n";
    contents += "3.신탁기간 만료일:" + dts_delistMaster.getCellData(1, "TRST_END_DD").substring(0, 4) + "." + dts_delistMaster.getCellData(1, "TRST_END_DD").substring(4, 6) + "." + dts_delistMaster.getCellData(1, "TRST_END_DD").substring(6, 8) + "\n";
    contents += "4.근거규정 :" + dts_delistMaster.getCellData(1, "GRND_REGUL_CONTN") + "\n";
    contents += "5.기타 투자판단에 참고할 사항 :" + dts_delistMaster.getCellData(1, "REMK") + "\n\n";
    //alert(contents);
    var userParam = [{
        uid: "ISUR_CD",
        unm: $c.stf.getObjectValue(txb_IsurCd)
    }, {
        uid: "COM_NM",
        unm: $c.stf.getObjectValue(txb_IsurNm)
    }, {
        uid: "TITLE",
        unm: $c.stf.getObjectValue(txb_title)
    }, {
        uid: "BODY",
        unm: contents
    }];
    $c.stf.doLogSave(scwin.vScrenID, SCREN_PROCS_TP_CD_05);
    //Rexpert 미리보기 호출 
    $c.rpt.fn_open_report(testDateSet, rex_rptname, userParam);
};
scwin.btn_Search_onclick = function() {
    if ($c.stf.getObjectValue(txb_IsurCd) == "") {
        $c.win.alert("[위탁회사]를 선택하세요.");
        txb_IsurNm.focus();
        return;
    } else {
        scwin.fn_init();
        scwin.fn_Search_list();
        buttonSet.setInsertStatus();
    }
};
scwin.img_COM_NM_onclick = function() {
    fn_GetPar = fn_GetParStdInd;
    fn_SetPar = fn_SetParStdInd;

    //fn_PopFindCorpChrg(vSecugrpID);
    $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
    scwin.fn_Search_list();
    buttonSet.setInsertStatus();
};
scwin.dts_list_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt1.setValue("총 " + dts_list.getTotalRow() + "건");
    var isur_cd = txb_IsurCd.getValue();
    scwin.fn_Search_Detaillist(isur_cd);
};
scwin.dts_detaillist_OnLoadCompleted = function(rowcount) {
    edt_TotalCnt.setValue("총 " + dts_detaillist.getTotalRow() + "건");
};
scwin.grd_delisting_OnClick = function(Row, Colid) {
    var temp = "";
    var content = "";
    var title = "";
    var count = 0;


    /*for (var i = 1; i <= dts_list.CountRow; i++) {
		if (dts_list.RowMark(i)  == 1)  {
            if (!temp)  {
                temp = dts_list.NameString(i, "ISU_KOR_NM");
            }
		}
    }*/

    //title = temp + " 수익증권 " +(count >= 2 ? "외" + (count - 1 ) + "건" : "") + " 상장폐지 예고안내";

    txb_title.setValue(dts_list.getCellData(Row, "ISU_KOR_NM") + " 수익증권 상장폐지 예고안내");
    txb_ISU_KOR_NM.setValue(dts_list.getCellData(Row, "ISU_KOR_NM"));
    txa_DELIST_ADVNOTI_RSN.Text = "신탁기간만료(" + dts_list.getCellData(Row, "TRST_END_DD").substring(0, 4) + "." + dts_list.getCellData(Row, "TRST_END_DD").substring(4, 6) + "." + dts_list.getCellData(Row, "TRST_END_DD").substring(6, 8) + ")시 상장폐지 예정";
    edt_TRST_END_DD.setValue(dts_list.getCellData(Row, "TRST_END_DD"));
    txa_GRND_REGUL_CONTN.Text = "유가증권시장상장 규정 제109조";
    txa_REMK.Text = "";
    txb_ISU_CD.setValue(dts_list.getCellData(Row, "ISU_CD"));
};
scwin.grd_Delistdetail_OnClick = function(row, colid) {
    var bzprocscd = dts_detaillist.getCellData(dts_detaillist.getRowPosition(), "BZ_PROCS_NO");
    scwin.fn_Search_delistMaster(bzprocscd);
    if (dts_detaillist.getCellData(dts_detaillist.getRowPosition(), "DISCLS_YN") == "Y") {
        buttonSet.setErrorStatus();
    } else {
        buttonSet.setUpdateStatus();
    }
};
scwin.trs_update_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    //var  isur_cd = dts_detaillist.nameValue(dts_detaillist.RowPosition, "ISUR_CD") ;
    var isur_cd = dts_delistMaster.getCellData(1, "ISUR_CD");
    scwin.fn_Search_Detaillist(isur_cd);
};
scwin.trs_update_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_update);
};
scwin.trs_delete_OnSuccess = function() {
    $c.lc.fn_alertMsg('S');
    //var  isur_cd = dts_detaillist.nameValue(dts_detaillist.RowPosition, "ISUR_CD") ;
    var isur_cd = dts_delistMaster.getCellData(1, "ISUR_CD");
    scwin.fn_Search_Detaillist(isur_cd);
    txb_title.setValue("");
    txb_ISU_KOR_NM.setValue("");
    txa_DELIST_ADVNOTI_RSN.Text = "";
    edt_TRST_END_DD.setValue("");
    txa_GRND_REGUL_CONTN.Text = "";
    txa_REMK.Text = "";
    txb_ISU_CD.setValue("");
    buttonSet.setInsertStatus();
};
scwin.trs_delete_OnFail = function() {
    $c.lc.fn_alertMsg('F');
    $c.stf.alert_error(trs_delete);
};
scwin.btn_New_onclick = function() {
    txb_title.setValue("");
    txb_ISU_KOR_NM.setValue("");
    txa_DELIST_ADVNOTI_RSN.Text = "";
    edt_TRST_END_DD.setValue("");
    txa_GRND_REGUL_CONTN.Text = "";
    txa_REMK.Text = "";
