    $c.libRoundPanel.PanelToGroupBox(panel_Top);
    $c.libRoundPanel.PanelToGroupBox(panel_Sub);
    dts_delistMaster.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELISTING_INOUT";
    dts_delistMaster.reset();
    dts_delistMaster.insertRow();
    dts_delistinsert.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=DELISTING_ISU_INOUT";
    dts_delistinsert.reset();

    //buttonSet.setInsertInfo( btn_New, fn_New ); 			
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장
    buttonSet.setUpdateInfo(btn_Update, fn_update); // 수정
    buttonSet.setDeleteInfo(btn_Delete, fn_delete); // 삭제
    buttonSet.setDsclInfo(btn_Dscl, fn_dscl); // 안내문작성
    //buttonSet.setMaktInfo( btn_Makt, fn_makt );				// 시장시스템전송

    buttonSet.setInsertStatus();
    buttonSet.setButtonSecugrpDepCd(dts_ByCorpDepCd, scwin.fr_SecuGrpId, $c.stf.getObjectValue(txb_IsurCd), js_dep_cd);
    $c.stf.showObj(label_1, false);
    $c.stf.showObj(txb_ISU_CD, false);
};
